import{_ as t,o as a,c as i,a0 as r}from"./chunks/framework.DPd3ST4h.js";const p=JSON.parse('{"title":"Checkout and exact-revision fetch benchmark","description":"","frontmatter":{},"headers":[],"relativePath":"checkout-benchmark.md","filePath":"checkout-benchmark.md","lastUpdated":1792931915000}'),o={name:"checkout-benchmark.md"};function s(n,e,c,l,h,d){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="checkout-and-exact-revision-fetch-benchmark" tabindex="-1">Checkout and exact-revision fetch benchmark <a class="header-anchor" href="#checkout-and-exact-revision-fetch-benchmark" aria-label="Permalink to &quot;Checkout and exact-revision fetch benchmark&quot;">​</a></h1><p>Redline reviews an exact pull request base and head. The repository checkout must therefore preserve all Git behavior used by the review pipeline:</p><ul><li>exact base and head objects, including fork heads and force-pushed commits;</li><li>complete <code>base..head</code> revision traversal and per-commit patch capture;</li><li>rename-aware and binary-aware diffs;</li><li>context-bundle base-file reads;</li><li>source exports for the review and both code-index revisions.</li></ul><p>Issue #127 is evidence-gated. Stage 1 adds the benchmark and correctness tests but does <strong>not</strong> change the production checkout. Stage 2 runs the merged workflow, checks in only its bounded aggregate JSON and Markdown report, and changes production behavior only if the agreed materiality and correctness gates pass.</p><p>The current aggregate is at <a href="https://github.com/dragoscirjan/redline/blob/main/benchmark/checkout/v1/report.md" target="_blank" rel="noreferrer"><code>benchmark/checkout/v1/report.md</code></a>. It remains pending until the manual workflow is available on the default branch.</p><h2 id="fixed-profile" tabindex="-1">Fixed profile <a class="header-anchor" href="#fixed-profile" aria-label="Permalink to &quot;Fixed profile&quot;">​</a></h2><p>The version-1 profile pins two public repositories and exact revisions:</p><ul><li>Redline as the small repository;</li><li>Microsoft Visual Studio Code as the large repository.</li></ul><p>Each strategy runs five times on a GitHub-hosted Ubuntu runner. The workflow rotates repository and strategy order between repetitions to reduce fixed ordering bias.</p><p>The strategies are:</p><ol><li><strong>Full</strong> — fetch all history reachable from the exact base, materialize the base worktree, then fetch the exact head.</li><li><strong>Shallow exact-revision</strong> — fetch the exact base at depth one, fetch the exact head at depth one, and deepen only until the base-to-head history is connected.</li><li><strong>Blobless partial</strong> — fetch complete commit and tree history with <code>blob:none</code>; checkout and authoritative Git operations hydrate required blobs.</li></ol><p>The benchmark does not use a Git object cache. Cache measurement becomes eligible only if the uncached result saves at least 30 seconds and at least 5% of the measured critical path.</p><h2 id="timing-boundaries" tabindex="-1">Timing boundaries <a class="header-anchor" href="#timing-boundaries" aria-label="Permalink to &quot;Timing boundaries&quot;">​</a></h2><p>Every sample reports these stages separately:</p><ul><li>checkout of the exact base, including its initial fetch and worktree materialization;</li><li>exact base/head fetch;</li><li>estimated object-hydration time, calculated from cold and warm authoritative operations;</li><li>warm context-bundle generation with its review head-source export;</li><li>warm base/head code-index source export;</li><li>the cold critical path used for the optimization decision;</li><li>local Git object-store bytes after each stage.</li></ul><p>The aggregate records minimum, nearest-rank p50, nearest-rank p95, and maximum values. The Markdown report presents p50/p95 pairs. Object-store bytes are not wire-level compressed transfer bytes. The report states this limit explicitly.</p><p>The benchmark runs the context bundle twice and exports both index source trees twice. The first operation can hydrate missing objects. The second operation supplies the warm execution baseline. The production-shaped critical path uses the first, cold duration; duplicate warm executions exist only to separate execution cost from hydration cost.</p><h2 id="correctness-gates" tabindex="-1">Correctness gates <a class="header-anchor" href="#correctness-gates" aria-label="Permalink to &quot;Correctness gates&quot;">​</a></h2><p>Every strategy must produce byte-equivalent SHA-256 digests for:</p><ul><li>the complete context bundle;</li><li>the review head-source export;</li><li>the sanitized base source export;</li><li>the sanitized head source export;</li><li>the ordered <code>git rev-list base..head</code> output.</li></ul><p>Deterministic local fixtures cover:</p><ul><li>merge commits;</li><li>shallow history deepening;</li><li>separate base and fork remotes;</li><li>a force-pushed branch whose reviewed head remains reachable only by its exact commit.</li></ul><p>A digest mismatch rejects that strategy. A mismatch among repeated full-checkout samples invalidates the capture because the reference itself is unstable. Rejected strategies cannot satisfy the materiality gate or make Git object caching eligible.</p><h2 id="decision-policy" tabindex="-1">Decision policy <a class="header-anchor" href="#decision-policy" aria-label="Permalink to &quot;Decision policy&quot;">​</a></h2><p>The report first finds the fastest correct strategy on the large repository. It then chooses the simplest correct strategy within 10% of that result, in this order:</p><ol><li>full;</li><li>shallow exact-revision;</li><li>blobless partial.</li></ol><p>A non-full strategy is only a production candidate when it saves at least 30,000 ms <strong>and</strong> 5% of the full strategy&#39;s nearest-rank p95 critical path. Otherwise Redline retains the current full-history behavior.</p><p>This benchmark does not establish the epic&#39;s model-review SLO. It only decides whether checkout and exact-revision Git work are material enough to optimize.</p><h2 id="run-the-benchmark" tabindex="-1">Run the benchmark <a class="header-anchor" href="#run-the-benchmark" aria-label="Permalink to &quot;Run the benchmark&quot;">​</a></h2><p>The live measurement is intentionally manual because it performs repeated public network fetches, including five full-history Visual Studio Code fetches.</p><ol><li>Open <strong>Actions → Checkout benchmark</strong>.</li><li>Run the workflow from the default branch.</li><li>Download <code>checkout-benchmark-&lt;run-id&gt;</code>.</li><li>Keep <code>raw/*.json</code> in the workflow artifact only.</li><li>Copy <code>aggregate.json</code> and <code>report.md</code> into <code>benchmark/checkout/v1/</code> in the stage-2 change.</li><li>Run <code>mise run benchmark:checkout</code> and <code>mise run validate</code>.</li></ol><p>The deterministic CI task only validates the profile/aggregate identity and regenerates the checked-in Markdown. Ordinary CI does not perform the live fetch benchmark.</p><h2 id="security-boundary" tabindex="-1">Security boundary <a class="header-anchor" href="#security-boundary" aria-label="Permalink to &quot;Security boundary&quot;">​</a></h2><p>The benchmark treats fetched repository content as data. It invokes argument-array Git commands and trusted Redline TypeScript only. It disables Git hooks and ambient Git configuration, does not initialize submodules, and never runs fetched scripts, builds, package installers, filters, or test commands.</p>',34)])])}const m=t(o,[["render",s]]);export{p as __pageData,m as default};
